use cumulus_core::catalog::metadata::{AlbumMetadata, ArtistCredit, ArtistMetadata};
use serde_json::json;

#[test]
fn frozen_official_normalizer_vectors_match_native_metadata() {
    // Generated by executing M/21 N/R with synthetic records. No recovered
    // JavaScript, accounts or external services are required by public CI.
    let vectors: Vec<serde_json::Value> =
        serde_json::from_str(include_str!("fixtures/catalog-metadata.json")).unwrap();
    for vector in vectors {
        let actual = match vector["kind"].as_str().unwrap() {
            "artist" => {
                serde_json::to_value(ArtistMetadata::from_official(&vector["input"]).unwrap())
            }
            "album" => {
                serde_json::to_value(AlbumMetadata::from_official(&vector["input"]).unwrap())
            }
            _ => panic!("unknown fixture"),
        }
        .unwrap();
        assert_eq!(actual, vector["expected"], "input: {}", vector["input"]);
    }
}

#[test]
fn artist_translation_preserves_normalizer_and_header_dedup_semantics() {
    let value = ArtistMetadata::from_official(&json!({
        "id":"90071992547409931234","name":"Artist","accountId":0,
        "alias":"别名;;译名;别名","trans":" 译名 ","transName":"不应采用",
        "fansSize":0,"fansCount":7,"followed":false
    }))
    .unwrap();
    assert_eq!(value.id, "90071992547409931234");
    assert_eq!(value.aliases, ["译名", "别名", "译名", "别名"]);
    assert_eq!(value.display_aliases(), ["译名", "别名"]);
    assert_eq!(value.fans_count, 7);
    assert_eq!(value.followed, Some(false));
    assert!(value.account_id.is_none());
    assert!(value.mv_count.is_none());
    let fallback =
        ArtistMetadata::from_official(&json!({"id":12,"alias":["别名"],"transName":" 译名 "}))
            .unwrap();
    assert_eq!(fallback.aliases, ["别名"]);
    assert_eq!(fallback.display_aliases(), ["译名", "别名"]);
    assert!(fallback.followed.is_none());
}

#[test]
fn default_artist_avatar_is_distinct_from_real_artwork() {
    for value in [
        json!({"id":12,"img1v1":-1,"img1v1Url":"https://p1.music.126.net/real.jpg"}),
        json!({"id":12,"img1v1":7,"img1v1Url":"https://p1.music.126.net/5639395138885805.jpg"}),
    ] {
        assert!(
            ArtistMetadata::from_official(&value)
                .unwrap()
                .avatar_url
                .is_empty()
        );
    }
    let image = "https://p1.music.126.net/real.jpg";
    let value =
        ArtistMetadata::from_official(&json!({"id":12,"img1v1Url":image,"picUrl":image})).unwrap();
    assert_eq!(value.avatar_url, image);
    assert_eq!(value.picture_url, image);
}

#[test]
fn album_legacy_names_counts_and_credits_follow_official_fallbacks() {
    let value = AlbumMetadata::from_official(&json!({
        "id":0,"albumId":"90071992547409931234","name":"","albumName":"旧专辑",
        "trackCount":0,"size":13,"subscribedCount":0,"subCount":9,"isSub":false,
        "cover":"","picUrl":"https://p1.music.126.net/a.jpg","pic_str":"9223372036854775807",
        "artist":{"id":12,"name":"歌手"},"artistName":"专辑署名",
        "artists":[{"id":12,"name":"第一位"},{"id":0,"name":"未关联"}],
        "publishTime":-12345,"mark":1048576
    }))
    .unwrap();
    assert_eq!(value.id, "90071992547409931234");
    assert_eq!(value.name, "旧专辑");
    assert_eq!((value.track_count, value.subscribed_count), (13, 9));
    assert_eq!(value.subscribed, Some(false));
    assert_eq!(value.primary_artist.as_ref().unwrap().name, "专辑署名");
    assert!(value.primary_artist.as_ref().unwrap().id.is_none());
    assert_eq!(value.artists[0].id.as_deref(), Some("12"));
    assert!(value.artists[1].id.is_none());
    assert_eq!(value.cover_id.as_deref(), Some("9223372036854775807"));
    assert_eq!(value.published_at, Some(-12345));
    assert!(value.explicit);
}

#[test]
fn empty_array_is_authoritative_and_unknown_membership_stays_unknown() {
    let value = AlbumMetadata::from_official(&json!({
        "id":7,"alia":[],"ala":["不应采用"],"alias":["不应采用"],
        "tns":[],"transNames":["不应采用"],"transName":"不应采用","picId":123
    }))
    .unwrap();
    assert!(value.aliases.is_empty() && value.translations.is_empty());
    assert!(value.subscribed.is_none());
    assert!(value.cover_id.is_none()); // R only enters the pic ID branch for pic_str/pic.
    let fallback = AlbumMetadata::from_official(&json!({
        "id":7,"ala":["别名"],"transName":"译名","artist":{"id":12,"name":"歌手"}
    }))
    .unwrap();
    assert_eq!(fallback.aliases, ["别名"]);
    assert_eq!(fallback.translations, ["译名"]);
    assert_eq!(fallback.primary_artist.unwrap().id.as_deref(), Some("12"));
}

#[test]
fn malformed_resource_ids_fail_while_unlinked_credits_are_displayable() {
    assert!(ArtistMetadata::from_official(&json!({"id":0})).is_err());
    assert!(AlbumMetadata::from_official(&json!({"id":"../7"})).is_err());
    let credit = ArtistCredit::from_official(&json!({"id":"invalid","name":"署名"}));
    assert!(credit.id.is_none());
    assert_eq!(credit.name, "署名");
    let artist = ArtistMetadata::from_official(&json!({"id":12,"cookie":"PRIVATE"})).unwrap();
    assert!(!serde_json::to_string(&artist).unwrap().contains("PRIVATE"));
}
